mapper.select:
SELECT
    mmpqc.*,
    mbp.name AS process_name,
    mbp.type AS process_type
FROM mes_machine_part_quota_config mmpqc
LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = mmpqc.process_id
WHERE mmpqc.bool_delete_enum = 0

    AND mmpqc.id = #{id}


    AND FIND_IN_SET(#{workshopId}, mmpqc.workshop_ids) > 0


    AND FIND_IN_SET(#{classId}, mmpqc.machine_part_class_ids) > 0


    
    AND mmpqc.quota_number LIKE #{quotaNumberLike}


    AND mmpqc.process_id = #{processId}


    AND mmpqc.machine_part_type = #{machinePartType}


    AND mmpqc.status = #{status}
